 int D(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} TextView T(String s,float z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,b?1:0);t.setPadding(0,D(5),0,D(5));return t;}
 LinearLayout page(String title){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(Color.rgb(7,16,28));LinearLayout h=new LinearLayout(this);h.setGravity(16);h.setPadding(D(16),D(12),D(16),D(8));TextView back=T("‹",38,Color.WHITE,false);back.setOnClickListener(v->finish());h.addView(back,new LinearLayout.LayoutParams(D(45),D(52)));h.addView(T(title,24,Color.WHITE,true),new LinearLayout.LayoutParams(0,D(52),1));r.addView(h);return r;}
 MaterialCardView card(String title,String sub){MaterialCardView c=new MaterialCardView(this);c.setRadius(D(20));c.setCardBackgroundColor(Color.rgb(19,31,48));c.setStrokeWidth(D(1));c.setStrokeColor(Color.rgb(40,62,84));LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(D(16),D(12),D(16),D(12));l.addView(T(title,17,Color.WHITE,true));l.addView(T(sub,12,Color.rgb(160,177,196),false));c.addView(l);return c;}
