 protected void onCreate(Bundle b){super.onCreate(b);String t=getIntent().getStringExtra("type");if("quran".equals(t))quran();else if("prayer".equals(t))prayer();else if("duas".equals(t))duas();else if("tasbih".equals(t))tasbih();else if("qibla".equals(t))qibla();else if("calendar".equals(t))calendar();else settings();}
 void quran(){LinearLayout r=page("Коран • القرآن");ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(20));g.addView(T("114 сур • арабский текст + перевод на таджикский",14,Color.rgb(158,178,198),false));String[] n={"Аль-Фатиха","Аль-Бакара","Али Имран","Ан-Ниса","Аль-Маида","Аль-Анам","Аль-Араф","Аль-Анфаль","Ат-Тауба","Юнус","Худ","Юсуф","Ар-Рад","Ибрахим","Аль-Хиджр","Ан-Нахль","Аль-Исра","Аль-Кахф","Марьям","Та Ха","Аль-Анбия","Аль-Хадж","Аль-Муминун","Ан-Нур","Аль-Фуркан","Аш-Шуара","Ан-Намль","Аль-Касас","Аль-Анкабут","Ар-Рум","Лукман","Ас-Саджда","Аль-Ахзаб","Саба","Фатыр","Я Син","Ас-Саффат","Сад","Аз-Зумар","Гафир","Фуссилят","Аш-Шура","Аз-Зухруф","Ад-Духан","Аль-Джасия","Аль-Ахкаф","Мухаммад","Аль-Фатх","Аль-Худжурат","Каф","Аз-Зарият","Ат-Тур","Ан-Наджм","Аль-Камар","Ар-Рахман","Аль-Вакиа","Аль-Хадид","Аль-Муджадила","Аль-Хашр","Аль-Мумтахана","Ас-Сафф","Аль-Джумуа","Аль-Мунафикун","Ат-Тагабун","Ат-Талак","Ат-Тахрим","Аль-Мульк","Аль-Калам","Аль-Хакка","Аль-Мааридж","Нух","Аль-Джинн","Аль-Муззаммиль","Аль-Муддассир","Аль-Кияма","Аль-Инсан","Аль-Мурсалят","Ан-Наба","Ан-Назиаат","Абаса","Ат-Таквир","Аль-Инфитар","Аль-Мутаффифин","Аль-Иншикак","Аль-Бурудж","Ат-Тарик","Аль-Ала","Аль-Гашия","Аль-Фаджр","Аль-Балад","Аш-Шамс","Аль-Лейль","Ад-Духа","Аш-Шарх","Ат-Тин","Аль-Алак","Аль-Кадр","Аль-Баййина","Аз-Зальзала","Аль-Адият","Аль-Кариа","Ат-Такасур","Аль-Аср","Аль-Хумаза","Аль-Филь","Курайш","Аль-Маун","Аль-Каусар","Аль-Кафирун","Ан-Наср","Аль-Масад","Аль-Ихляс","Аль-Фаляк","Ан-Нас"};for(int i=0;i<114;i++){final int no=i+1;MaterialCardView c=card(String.format(Locale.US,"%03d  %s",no,n[i]),"Открыть суру • "+no);c.setOnClickListener(v->surah(no,n[no-1]));add(g,c,72);}s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 void surah(int no,String name){LinearLayout r=page(name);ProgressBar p=new ProgressBar(this);p.setIndeterminate(true);r.addView(p,new LinearLayout.LayoutParams(-1,D(55)));TextView info=T("Загрузка арабского текста и таджикского перевода…",13,Color.LTGRAY,false);r.addView(info);ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),D(8),D(16),D(30));s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);new Thread(()->{try{String key="surah_"+no;String cached=getPreferences(0).getString(key,null);String json=cached!=null?cached:get("https://api.alquran.cloud/v1/surah/"+no+"/editions/quran-uthmani,tg.ayati");if(cached==null)getPreferences(0).edit().putString(key,json).apply();JSONObject root=new JSONObject(json);JSONArray data=root.getJSONArray("data");JSONArray ar=data.getJSONObject(0).getJSONArray("ayahs");JSONArray tg=data.length()>1?data.getJSONObject(1).getJSONArray("ayahs"):new JSONArray();runOnUiThread(()->{p.setVisibility(View.GONE);info.setText("Источник текста: AlQuran Cloud • перевод: АбдолМухаммад Оятӣ");for(int i=0;i<ar.length();i++)try{JSONObject a=ar.getJSONObject(i);String tr=tg.length()>i?tg.getJSONObject(i).optString("text","Перевод недоступен"): "Перевод недоступен";LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(D(14),D(10),D(14),D(10));box.setBackgroundColor(Color.rgb(13,24,39));TextView aa=T(a.optString("text"),23,Color.rgb(247,239,216),false);aa.setGravity(Gravity.RIGHT);aa.setTextDirection(View.TEXT_DIRECTION_RTL);box.addView(aa);box.addView(T("﴾ "+a.optInt("numberInSurah")+" ﴿",12,Color.rgb(100,192,171),true));box.addView(T(tr,15,Color.rgb(190,201,214),false));add(g,box,0); }catch(Exception e){} });}catch(Exception e){runOnUiThread(()->{p.setVisibility(View.GONE);info.setText("Не удалось загрузить эту суру. Проверь интернет и повтори.");});}}).start();}
 String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestMethod("GET");BufferedReader b=new BufferedReader(new InputStreamReader(c.getInputStream(),"UTF-8"));StringBuilder s=new StringBuilder();String x;while((x=b.readLine())!=null)s.append(x);b.close();return s.toString();}
 void prayer(){LinearLayout r=page("Время намаза");ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(24));g.addView(T("Время рассчитывается по координатам телефона и часовому поясу устройства.",13,Color.rgb(160,178,198),false));Calendar c=Calendar.getInstance();for(PrayerTime x:PrayerCalculator.calculate(PrayerSettings.latitude(this),PrayerSettings.longitude(this),c,TimeZone.getDefault(),PrayerSettings.method(this),PrayerSettings.school(this)))add(g,card(x.name(),x.time()+"  •  уведомление"),72);g.addView(T("Метод: MWL • мазхаб Аср: Hanafi",13,Color.rgb(130,150,170),false));s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 void duas(){LinearLayout r=page("Дуа • دعاء");ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(24));String[][] d={{"1. После пробуждения","الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور","Ситоиш Аллоҳро, ки моро баъд аз марг зинда кард."},{"2. Перед едой","بسم الله","Ба номи Аллоҳ."},{"3. После еды","الحمد لله الذي أطعمنا وسقانا","Ситоиш Аллоҳро барои ризқ ва нӯшокӣ."},{"4. Перед сном","باسمك اللهم أموت وأحيا","Ба номи Ту, эй Аллоҳ, мемираму зинда мешавам."},{"5. О просьбе о прощении","رب اغفر لي","Парвардигоро, маро биёмурз."},{"6. О добре в мире","ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة","Парвардигоро, дар дунё ва охират ба мо некӣ бидеҳ."},{"7. О знании","رب زدني علما","Парвардигоро, илми маро зиёд кун."},{"8. О родителях","رب ارحمهما كما ربياني صغيرا","Парвардигоро, ба онҳо раҳм кун, чунон ки маро хурд тарбия карданд."},{"9. От тревоги","حسبي الله لا إله إلا هو عليه توكلت","Аллоҳ барои ман кофист; бар Ӯ таваккал кардам."},{"10. О руководстве","اهدنا الصراط المستقيم","Моро ба роҳи рост ҳидоят кун."}};for(int i=0;i<50;i++){String[] x=d[i%10];add(g,card(x[0],x[1]+"\n"+x[2]),96);}s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 void tasbih(){
  boolean tg="tg".equals(LanguageManager.getLanguage(this));
  LinearLayout r=page(tg?"Тасбеҳ • تسبيح":"Тасбих • تسبيح");
  LinearLayout g=new LinearLayout(this);g.setGravity(17);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(24),D(24),D(24),D(24));
  android.content.SharedPreferences prefs=getSharedPreferences("namoz_tasbih",MODE_PRIVATE);
  String[] arabic={"سُبْحَانَ اللّٰهِ","الْحَمْدُ لِلّٰهِ","اللّٰهُ أَكْبَرُ","لَا إِلٰهَ إِلَّا اللّٰهُ"};
  String[] ru={"Субханаллах","Альхамдулиллях","Аллаху акбар","Ля иляха илляллах"};
  String[] tj={"Субҳаналлоҳ","Алҳамдулиллоҳ","Аллоҳу акбар","Ло илоҳа иллаллоҳ"};
  int[] state={Math.max(0,prefs.getInt("count",0)),Math.max(0,prefs.getInt("phrase",0))%4};
  TextView hint=T(tg?"Зикрро интихоб карда, оромона такрор кунед":"Выберите зикр и повторяйте его осознанно",14,Color.rgb(160,178,198),false);hint.setGravity(17);g.addView(hint);
  TextView zik=T(arabic[state[1]],30,Color.rgb(112,205,178),true);zik.setGravity(17);g.addView(zik,new LinearLayout.LayoutParams(-1,D(90)));
  TextView translit=T((tg?tj:ru)[state[1]],21,Color.WHITE,true);translit.setGravity(17);g.addView(translit);
  TextView progress=T("",14,Color.rgb(160,178,198),false);progress.setGravity(17);g.addView(progress);
  TextView num=T(String.valueOf(state[0]),66,Color.WHITE,true);num.setGravity(17);g.addView(num,new LinearLayout.LayoutParams(-1,D(110)));
  Runnable refresh=()->{num.setText(String.valueOf(state[0]));zik.setText(arabic[state[1]]);translit.setText((tg?tj:ru)[state[1]]);progress.setText((tg?"Давр: ":"Цикл: ")+(state[0]/33+1)+" • "+(state[0]%33)+"/33");};refresh.run();
  Button tap=new Button(this);tap.setText(tg?"ЗИКР  +1":"ТАСБИХ  +1");tap.setTextSize(18);tap.setOnClickListener(v->{state[0]++;if(state[0]%33==0)state[1]=(state[1]+1)%4;prefs.edit().putInt("count",state[0]).putInt("phrase",state[1]).apply();refresh.run();});g.addView(tap,new LinearLayout.LayoutParams(-1,D(62)));
  Button next=new Button(this);next.setText(tg?"Зикри навбатӣ":"Следующий зикр");next.setOnClickListener(v->{state[1]=(state[1]+1)%4;prefs.edit().putInt("phrase",state[1]).apply();refresh.run();});g.addView(next,new LinearLayout.LayoutParams(-1,D(54)));
  Button reset=new Button(this);reset.setText(tg?"Аз нав сар кардан":"Сбросить счётчик");reset.setOnClickListener(v->{state[0]=0;prefs.edit().putInt("count",0).apply();refresh.run();});g.addView(reset,new LinearLayout.LayoutParams(-1,D(54)));
  TextView note=T(tg?"Ҳисоб дар телефон нигоҳ дошта мешавад. Пас аз ҳар 33 такрор зикри навбатӣ пешниҳод мешавад.":"Счёт сохраняется на телефоне. После каждых 33 повторений предлагается следующий зикр.",12,Color.rgb(130,150,170),false);note.setGravity(17);g.addView(note);
  r.addView(g,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);
 }
 void qibla(){
  boolean tg="tg".equals(LanguageManager.getLanguage(this));
  LinearLayout r=page(tg?"Қибла":"Кибла");LinearLayout g=new LinearLayout(this);g.setGravity(17);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(22),D(24),D(22),D(24));
  double lat=PrayerSettings.latitude(this),lon=PrayerSettings.longitude(this);
  double bearing=Math.toDegrees(Math.atan2(Math.sin(Math.toRadians(39.8262-lon))*Math.cos(Math.toRadians(21.4225)),Math.cos(Math.toRadians(lat))*Math.sin(Math.toRadians(21.4225))-Math.sin(Math.toRadians(lat))*Math.cos(Math.toRadians(21.4225))*Math.cos(Math.toRadians(39.8262-lon))));bearing=(bearing+360)%360;final double qiblaBearing=bearing;
  TextView compass=T("➤",92,Color.rgb(112,205,178),true);compass.setGravity(17);g.addView(compass,new LinearLayout.LayoutParams(-1,D(180)));
  TextView degree=T("",22,Color.WHITE,true);degree.setGravity(17);g.addView(degree);
  TextView status=T("",13,Color.rgb(160,178,198),false);status.setGravity(17);g.addView(status);
  degree.setText(String.format(Locale.US,tg?"Самт: %.0f° аз шимол":"Направление: %.0f° от севера",bearing));
  SensorManager sm=(SensorManager)getSystemService(SENSOR_SERVICE);Sensor rotation=sm==null?null:sm.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);
  if(rotation!=null){
   status.setText(tg?"Телефонро ҳамвор нигоҳ доред ва ба самти нишондиҳанда гардонед.":"Держите телефон горизонтально и поворачивайте его по стрелке.");
   SensorEventListener listener=new SensorEventListener(){public void onAccuracyChanged(Sensor sensor,int accuracy){} public void onSensorChanged(SensorEvent event){float[] matrix=new float[9];float[] orientation=new float[3];SensorManager.getRotationMatrixFromVector(matrix,event.values);SensorManager.getOrientation(matrix,orientation);float azimuth=(float)Math.toDegrees(orientation[0]);compass.setRotation((float)qiblaBearing-azimuth);}};
   sm.registerListener(listener,rotation,SensorManager.SENSOR_DELAY_UI);qiblaListener=listener;
  }else status.setText(tg?"Датчики қутбнамо дар ин телефон дастрас нестанд.":"На этом телефоне нет датчика компаса.");
  TextView foot=T(tg?"Самт аз рӯи координатҳои ҷойгиршавӣ ҳисоб карда шудааст.":"Направление рассчитано по координатам местоположения.",12,Color.rgb(130,150,170),false);foot.setGravity(17);g.addView(foot);
  r.addView(g,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);
 }
 void calendar(){LinearLayout r=page("Исламский календарь");LinearLayout g=new LinearLayout(this);g.setGravity(17);g.setOrientation(LinearLayout.VERTICAL);g.addView(T(new SimpleDateFormat("dd MMMM yyyy",new Locale("ru")).format(new Date()),25,Color.WHITE,true));g.addView(T("Сегодня • дата устройства\nХиджрийская дата будет вынесена в отдельный офлайн-модуль.",14,Color.LTGRAY,false));r.addView(g,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 void settings(){LinearLayout r=page("Настройки");LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(20));g.addView(T("Язык",15,Color.LTGRAY,true));Button tg=new Button(this);tg.setText("Тоҷикӣ");tg.setOnClickListener(v->{LanguageManager.setLanguage(this,"tg");recreate();});g.addView(tg);Button ru=new Button(this);ru.setText("Русский");ru.setOnClickListener(v->{LanguageManager.setLanguage(this,"ru");recreate();});g.addView(ru);g.addView(T("Метод расчёта времени",15,Color.LTGRAY,true));Button mwl=new Button(this);mwl.setText("Muslim World League");mwl.setOnClickListener(v->PrayerSettings.saveCalculation(this,PrayerCalculator.METHOD_MWL,PrayerCalculator.SCHOOL_HANAFI));g.addView(mwl);Button eg=new Button(this);eg.setText("Egyptian");eg.setOnClickListener(v->PrayerSettings.saveCalculation(this,PrayerCalculator.METHOD_EGYPT,PrayerCalculator.SCHOOL_HANAFI));g.addView(eg);g.addView(T("Нажми «Время намаза» после изменения настроек.",13,Color.LTGRAY,false));r.addView(g,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
